create extension if not exists pgcrypto;
create table if not exists businesses(id uuid primary key default gen_random_uuid(), name text not null, preferred_language text default 'English', owner_user_id uuid references auth.users(id) on delete cascade, created_at timestamptz default now());
create table if not exists business_members(id uuid primary key default gen_random_uuid(), business_id uuid references businesses(id) on delete cascade, user_id uuid references auth.users(id) on delete cascade, role text default 'owner', unique(business_id,user_id));
create table if not exists phone_numbers(id uuid primary key default gen_random_uuid(), business_id uuid references businesses(id) on delete set null, phone_number text unique not null, provider text default 'telnyx', provider_id text, status text default 'pending', created_at timestamptz default now());
create table if not exists contacts(id uuid primary key default gen_random_uuid(), business_id uuid references businesses(id) on delete cascade, name text, phone text, email text, preferred_language text, lead_status text default 'New', marketing_sms_consent boolean default false, sms_opted_out boolean default false, created_at timestamptz default now(), unique(business_id,phone));
create table if not exists conversations(id uuid primary key default gen_random_uuid(), business_id uuid references businesses(id) on delete cascade, contact_id uuid references contacts(id) on delete cascade, phone_number_id uuid references phone_numbers(id) on delete cascade, last_message_at timestamptz default now());
create table if not exists messages(id uuid primary key default gen_random_uuid(), business_id uuid references businesses(id) on delete cascade, conversation_id uuid references conversations(id) on delete cascade, direction text not null, from_number text, to_number text, body text not null, translated_body text, provider_message_id text, status text default 'queued', created_at timestamptz default now());
create table if not exists invoices(id uuid primary key default gen_random_uuid(), business_id uuid references businesses(id) on delete cascade, contact_id uuid references contacts(id) on delete set null, amount_cents integer not null, description text, status text default 'draft', stripe_payment_link text, due_at timestamptz, paid_at timestamptz, created_at timestamptz default now());
create table if not exists automations(id uuid primary key default gen_random_uuid(), business_id uuid references businesses(id) on delete cascade, name text not null, trigger_type text not null, action_type text not null, enabled boolean default true, config jsonb default '{}'::jsonb, created_at timestamptz default now());
create table if not exists automation_runs(id uuid primary key default gen_random_uuid(), automation_id uuid references automations(id) on delete cascade, business_id uuid references businesses(id) on delete cascade, run_at timestamptz not null, status text default 'scheduled', payload jsonb default '{}'::jsonb, created_at timestamptz default now());
create table if not exists subscriptions(id uuid primary key default gen_random_uuid(), business_id uuid references businesses(id) on delete cascade, stripe_customer_id text, status text default 'free', plan text default 'free', created_at timestamptz default now());

alter table businesses enable row level security; alter table business_members enable row level security; alter table phone_numbers enable row level security; alter table contacts enable row level security; alter table conversations enable row level security; alter table messages enable row level security; alter table invoices enable row level security; alter table automations enable row level security; alter table automation_runs enable row level security; alter table subscriptions enable row level security;

create or replace function is_business_member(bid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from business_members where business_id=bid and user_id=auth.uid()) or exists(select 1 from businesses where id=bid and owner_user_id=auth.uid()); $$;
create policy "business owner reads business" on businesses for select using(owner_user_id=auth.uid() or is_business_member(id));
create policy "business owner updates business" on businesses for update using(owner_user_id=auth.uid());
create policy "user creates own business" on businesses for insert with check(owner_user_id=auth.uid());
create policy "members readable" on business_members for select using(user_id=auth.uid() or is_business_member(business_id));
create policy "owner manages members" on business_members for all using(is_business_member(business_id));
create policy "tenant phone numbers" on phone_numbers for all using(is_business_member(business_id)) with check(is_business_member(business_id));
create policy "tenant contacts" on contacts for all using(is_business_member(business_id)) with check(is_business_member(business_id));
create policy "tenant conversations" on conversations for all using(is_business_member(business_id)) with check(is_business_member(business_id));
create policy "tenant messages" on messages for all using(is_business_member(business_id)) with check(is_business_member(business_id));
create policy "tenant invoices" on invoices for all using(is_business_member(business_id)) with check(is_business_member(business_id));
create policy "tenant automations" on automations for all using(is_business_member(business_id)) with check(is_business_member(business_id));
create policy "tenant automation runs" on automation_runs for all using(is_business_member(business_id)) with check(is_business_member(business_id));
create policy "tenant subscriptions" on subscriptions for all using(is_business_member(business_id)) with check(is_business_member(business_id));
